    pickerTap: function pickerTap() {
      date = new Date();
      var monthDay = ['今天', '明天'];
      var hours = [];
      var minute = [];
      currentHours = date.getHours();
      currentMinute = date.getMinutes(); // 月-日

      for (var i = 2; i <= 28; i++) {
        var date1 = new Date(date);
        date1.setDate(date.getDate() + i);
        var md = date1.getMonth() + 1 + "-" + date1.getDate();
        monthDay.push(md);
      }

      var data = {
        multiArray: this.multiArray,
        multiIndex: this.multiIndex };


      if (data.multiIndex[0] === 0) {
        if (data.multiIndex[1] === 0) {
          this.loadData(hours, minute);
        } else {
          this.loadMinute(hours, minute);
        }
      } else {
        this.loadHoursMinute(hours, minute);
      }

      data.multiArray[0] = monthDay;
      data.multiArray[1] = hours;
      data.multiArray[2] = minute;
      this.setData(data);
    },
    bindMultiPickerColumnChange: function bindMultiPickerColumnChange(e) {
      date = new Date();
      var that = this;
      var monthDay = ['今天', '明天'];
      var hours = [];
      var minute = [];
      currentHours = date.getHours();
      currentMinute = date.getMinutes();
      var data = {
        multiArray: this.multiArray,
        multiIndex: this.multiIndex };
      // 把选择的对应值赋值给 multiIndex

      data.multiIndex[e.detail.column] = e.detail.value; // 然后再判断当前改变的是哪一列,如果是第1列改变

      if (e.detail.column === 0) {
        // 如果第一列滚动到第一行
        if (e.detail.value === 0) {
          that.loadData(hours, minute);
        } else {
          that.loadHoursMinute(hours, minute);
        }

        data.multiIndex[1] = 0;
        data.multiIndex[2] = 0; // 如果是第2列改变
      } else if (e.detail.column === 1) {
        // 如果第一列为今天
        if (data.multiIndex[0] === 0) {
          if (e.detail.value === 0) {
            that.loadData(hours, minute);
          } else {
            that.loadMinute(hours, minute);
          } // 第一列不为今天

        } else {
          that.loadHoursMinute(hours, minute);
        }

        data.multiIndex[2] = 0; // 如果是第3列改变
      } else {
        // 如果第一列为'今天'
        if (data.multiIndex[0] === 0) {
          // 如果第一列为 '今天'并且第二列为当前时间
          if (data.multiIndex[1] === 0) {
            that.loadData(hours, minute);
          } else {
            that.loadMinute(hours, minute);
          }
        } else {
          that.loadHoursMinute(hours, minute);
        }
      }

      data.multiArray[1] = hours;
      data.multiArray[2] = minute;
      this.setData(data);
    },
    loadData: function loadData(hours, minute) {
      var minuteIndex;

      if (currentMinute > 0 && currentMinute <= 10) {
        minuteIndex = 10;
      } else if (currentMinute > 10 && currentMinute <= 20) {
        minuteIndex = 20;
      } else if (currentMinute > 20 && currentMinute <= 30) {
        minuteIndex = 30;
      } else if (currentMinute > 30 && currentMinute <= 40) {
        minuteIndex = 40;
      } else if (currentMinute > 40 && currentMinute <= 50) {
        minuteIndex = 50;
      } else {
        minuteIndex = 60;
      }

      if (minuteIndex == 60) {
        // 时
        for (var i = currentHours + 1; i < 24; i++) {
          hours.push(i);
        } // 分


        for (var i = 0; i < 60; i += 10) {
          minute.push(i);
        }
      } else {
        // 时
        for (var i = currentHours; i < 24; i++) {
          hours.push(i);
        } // 分


        for (var i = minuteIndex; i < 60; i += 10) {
          minute.push(i);
        }
      }
    },
    loadHoursMinute: function loadHoursMinute(hours, minute) {
      // 时
      for (var i = 0; i < 24; i++) {
        hours.push(i);
      } // 分


      for (var i = 0; i < 60; i += 10) {
        minute.push(i);
      }
    },
    loadMinute: function loadMinute(hours, minute) {
      var minuteIndex;

      if (currentMinute > 0 && currentMinute <= 10) {
        minuteIndex = 10;
      } else if (currentMinute > 10 && currentMinute <= 20) {
        minuteIndex = 20;
      } else if (currentMinute > 20 && currentMinute <= 30) {
        minuteIndex = 30;
      } else if (currentMinute > 30 && currentMinute <= 40) {
        minuteIndex = 40;
      } else if (currentMinute > 40 && currentMinute <= 50) {
        minuteIndex = 50;
      } else {
        minuteIndex = 60;
      }

      if (minuteIndex == 60) {
        // 时
        for (var i = currentHours + 1; i < 24; i++) {
          hours.push(i);
        }
      } else {
        // 时
        for (var i = currentHours; i < 24; i++) {
          hours.push(i);
        }
      } // 分


      for (var i = 0; i < 60; i += 10) {
        minute.push(i);
      }
    },
    bindStartMultiPickerChange: function bindStartMultiPickerChange(e) {
      var that = this;
      var monthDay = that.multiArray[0][e.detail.value[0]];
      var hours = that.multiArray[1][e.detail.value[1]];
      var minute = that.multiArray[2][e.detail.value[2]];

      if (monthDay === "今天") {
        var month = date.getMonth() + 1;
        var day = date.getDate();
        monthDay = month + "月" + day + "日";
      } else if (monthDay === "明天") {
        var date1 = new Date(date);
        date1.setDate(date.getDate() + 1);
        monthDay = date1.getMonth() + 1 + "月" + date1.getDate() + "日";
      } else {
        var month = monthDay.split("-")[0]; // 返回月

        var day = monthDay.split("-")[1]; // 返回日

        monthDay = month + "月" + day + "日";
      }

      var startDate = monthDay + " " + hours + ":" + minute;
      that.setData({
        startDate: startDate });

    },
